import { z } from 'zod';
import { SourceSyncModeSchema } from './source-sync';
import type {
  ProfileObservation,
  ProfileProvider,
  ProfileReference,
} from './design-profile';
import {
  ProfileObservationSchema,
  ProfileProviderSchema,
  ProfileReferenceSchema,
  ProfileRuntimeSchema,
  ReferenceAutonomySchema,
  RemoteProfileProviderSchema,
  PROFILE_IMPORT_STEPS,
} from './design-profile';

export const DesignLibrarySourceSchema = z.object({
  id: z.string(),
  title: z.string(),
  provider: ProfileProviderSchema,
  isIncluded: z.boolean(),
  syncMode: SourceSyncModeSchema,
});
export type DesignLibrarySource = z.infer<typeof DesignLibrarySourceSchema>;

export const UPLOADED_SOURCE_FILTER_ID = 'uploaded';
const UPLOADED_SOURCE_PROVIDER: ProfileProvider = 'image';

type SourceIdentity = Pick<DesignLibrarySource, 'id' | 'title' | 'provider'>;

export interface DesignLibrarySourceFilter {
  id: string;
  title: string;
  provider: ProfileProvider;
  sourceIds: string[];
}

export const designLibrarySourceFilters = (
  sources: SourceIdentity[],
): DesignLibrarySourceFilter[] => {
  const uploadIds = sources
    .filter((source) => source.provider === UPLOADED_SOURCE_PROVIDER)
    .map((source) => source.id);
  const uploaded: DesignLibrarySourceFilter[] = uploadIds.length
    ? [
        {
          id: UPLOADED_SOURCE_FILTER_ID,
          title: 'Uploaded',
          provider: UPLOADED_SOURCE_PROVIDER,
          sourceIds: uploadIds,
        },
      ]
    : [];
  return [
    ...uploaded,
    ...sources
      .filter((source) => source.provider !== UPLOADED_SOURCE_PROVIDER)
      .map(({ id, title, provider }) => ({
        id,
        title,
        provider,
        sourceIds: [id],
      })),
  ];
};

export const sourceIdsInFilter = ({
  sources,
  filterId,
}: {
  sources: SourceIdentity[];
  filterId: string;
}): string[] =>
  designLibrarySourceFilters(sources).find((filter) => filter.id === filterId)
    ?.sourceIds ?? [filterId];

export const DesignLibraryReferenceSchema = ProfileReferenceSchema.extend({
  sourceIds: z.array(z.string()),
  observation: ProfileObservationSchema.nullable(),
});
export type DesignLibraryReference = z.infer<
  typeof DesignLibraryReferenceSchema
>;

export const DesignLibraryImportReasonSchema = z.enum([
  'rate_limited',
  'source_unavailable',
  'images_unavailable',
  'agent_unavailable',
  'agent_failed',
  'search_unsupported',
  'search_unavailable',
  'unknown',
]);
export type DesignLibraryImportReason = z.infer<
  typeof DesignLibraryImportReasonSchema
>;

export const DesignLibraryImportDiagnosticsSchema = z.object({
  failedStep: z.enum(PROFILE_IMPORT_STEPS).nullable(),
  reasonCode: z.string().nullable(),
  detail: z.string().nullable(),
  platform: z.string(),
  arch: z.string(),
  nodeVersion: z.string(),
});

export const DesignLibraryImportSchema = z.object({
  jobId: z.string(),
  provider: RemoteProfileProviderSchema,
  state: z.enum(['pending', 'failed']),
  referenceCount: z.number().int().nonnegative(),
  analyzedCount: z.number().int().nonnegative(),
  reason: DesignLibraryImportReasonSchema.nullable(),
  diagnostics: DesignLibraryImportDiagnosticsSchema.nullable(),
});
export type DesignLibraryImport = z.infer<typeof DesignLibraryImportSchema>;

export const DesignLibrarySnapshotSchema = z.object({
  profileId: z.string(),
  revision: z.number(),
  isEnabled: z.boolean(),
  sources: z.array(DesignLibrarySourceSchema),
  references: z.array(DesignLibraryReferenceSchema),
  imports: z.array(DesignLibraryImportSchema),
});
export type DesignLibrarySnapshot = z.infer<typeof DesignLibrarySnapshotSchema>;

export const DESIGN_LIBRARY_PATH = '/rivet/library/references';

export const designLibraryEntryPath = (referenceId: string): string =>
  `${DESIGN_LIBRARY_PATH}/${encodeURIComponent(referenceId)}`;

export const DesignReferenceSearchRequestSchema = z.object({
  query: z.string().trim().min(2).max(1000),
  sourceId: z.string().min(1).max(200).optional(),
  limit: z.number().int().min(1).max(100).default(24),
  runtime: ProfileRuntimeSchema.default('codex'),
  isAgentSearch: z.boolean().optional(),
});
export type DesignReferenceSearchRequest = z.infer<
  typeof DesignReferenceSearchRequestSchema
>;

export const AGENT_SEARCH_STATUSES = [
  'ok',
  'unsupported_platform',
  'not_installed',
  'engine_starting',
  'engine_failed',
  'engine_busy',
  'model_call_refused',
  'not_indexed',
] as const;
export type AgentSearchStatus = (typeof AGENT_SEARCH_STATUSES)[number];

export const ReferenceSearchModeSchema = z.enum(['semantic', 'saved_text']);
export type ReferenceSearchMode = z.infer<typeof ReferenceSearchModeSchema>;

export type DesignLibraryMatch = DesignLibraryReference & {
  matchedBy: ReferenceSearchMode;
};

export const DesignReferenceSearchResultSchema = z.object({
  profileId: z.string(),
  query: z.string(),
  coverage: z.object({
    saved: z.number(),
    analyzed: z.number(),
    provisional: z.number(),
    indexed: z.number(),
  }),
  results: z.array(
    z.object({
      id: z.string(),
      key: z.string(),
      title: z.string(),
      provider: ProfileProviderSchema,
      url: z.string().optional(),
      description: z.string().nullable(),
      hasAnalysis: z.boolean(),
      matchedBy: ReferenceSearchModeSchema,
      imageCount: z.number(),
      sources: z.array(DesignLibrarySourceSchema),
      isIncluded: z.boolean(),
    }),
  ),
});
export type DesignReferenceSearchResult = z.infer<
  typeof DesignReferenceSearchResultSchema
>;

export const AgentReferenceSearchResultSchema =
  DesignReferenceSearchResultSchema.extend({
    status: z.enum(AGENT_SEARCH_STATUSES),
    searchMode: ReferenceSearchModeSchema,
    autonomy: ReferenceAutonomySchema,
    coverage: DesignReferenceSearchResultSchema.shape.coverage.extend({
      pendingIndex: z.number(),
    }),
  });
export type AgentReferenceSearchResult = z.infer<
  typeof AgentReferenceSearchResultSchema
>;

export const DESIGN_REFERENCE_BATCH_LIMIT = 50;
const REFERENCE_PREFIX_LENGTH = 12;

export const DesignReferenceKeySchema = z
  .string()
  .regex(/^[a-f0-9]{12,64}@[1-9][0-9]*$/)
  .refine(
    (key) => Number.isSafeInteger(Number(key.split('@')[1])),
    'Invalid reference revision',
  );

export const DesignReferenceRequestSchema = z.object({
  profileId: z.string().uuid(),
  keys: z
    .array(DesignReferenceKeySchema)
    .min(1)
    .max(DESIGN_REFERENCE_BATCH_LIMIT),
  isDetailed: z.boolean().default(false),
});
export type DesignReferenceRequest = z.infer<
  typeof DesignReferenceRequestSchema
>;

export const designReferenceKeys = (
  items: Pick<ProfileReference, 'id' | 'revision'>[],
): Map<string, string> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    const prefix = item.id.slice(0, REFERENCE_PREFIX_LENGTH);
    counts.set(prefix, (counts.get(prefix) ?? 0) + 1);
  }
  return new Map(
    items.map((item) => {
      const prefix = item.id.slice(0, REFERENCE_PREFIX_LENGTH);
      const id = counts.get(prefix) === 1 ? prefix : item.id;
      return [item.id, `${id}@${item.revision}`];
    }),
  );
};

export interface DesignReferenceSummary {
  key: string;
  title: string;
  imageCount: number;
  hasAnalysis: boolean;
}

export interface DesignReferenceContext extends DesignReferenceSummary {
  text: string;
  note?: string;
  analysis: Pick<ProfileObservation, 'description' | 'evidence'> | null;
  sources: DesignLibrarySource[];
  contextImages: string[];
  missingMediaCount: number;
}
